import re,numpy as np
from collections import deque
lines=open('/workspace/text.gcode').read().splitlines()
obj=None;x=y=z=None;segs=[]
for l in lines:
    s=l.strip();m=re.match(r'M486 S(-?\d+)',s)
    if m:
        v=int(m.group(1));obj=v if v>=0 else None;continue
    if obj!=0:continue
    if not (s.startswith('G1') or s.startswith('G2') or s.startswith('G3')):continue
    def g(k,d):
        mm=re.search(r'\b'+k+r'([-\d.]+)',s);return float(mm.group(1)) if mm else d
    nx=g('X',x);ny=g('Y',y);nz=g('Z',z)
    extruding=('E' in s) and not re.search(r'E-',s)
    if x is not None and ('X' in s or 'Y' in s):segs.append((x,y,z,nx,ny,nz,extruding))
    x,y,z=nx,ny,nz
E=np.array([(p[0],p[1],p[2]) for p in segs if p[6]]+[(p[3],p[4],p[5]) for p in segs if p[6]])
mu=E.mean(0);X=E-mu;w,V=np.linalg.eigh(X.T@X/len(X));idx=np.argsort(w)[::-1];w=w[idx];V=V[:,idx]
def proj(p):q=(np.array(p[:3])-mu)@V;return q[0],q[1]
Q=[proj(p[:3]) for p in segs if p[6]];R=[proj(p[3:6]) for p in segs if p[6]]
pts=Q+R
minx=min(p[0] for p in pts);maxx=max(p[0] for p in pts);miny=min(p[1] for p in pts);maxy=max(p[1] for p in pts)
W=int((maxx-minx)/0.15);H=int((maxy-miny)/0.15)+1
grid=np.zeros((H,W),dtype=bool)
def plot(px,py):
    cx=int((px-minx)/0.15);cy=H-1-int((py-miny)/0.15)
    if 0<=cx<W and 0<=cy<H:grid[cy,cx]=1
for a,b in zip(Q,R):
    n=max(1,int(max(abs(b[0]-a[0]),abs(b[1]-a[1]))/0.15*2))
    for i in range(n+1):
        t=i/n;plot(a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t)
# dilate 1 pixel to close contours
g=grid.copy()
for dy in (-1,0,1):
 for dx in (-1,0,1):
  g|=np.roll(np.roll(grid,dy,0),dx,1)
seen=np.zeros_like(g);comps=[]
for yy in range(H):
 for xx in range(W):
  if g[yy,xx] and not seen[yy,xx]:
   q=deque([(yy,xx)]);seen[yy,xx]=1;minc=maxc=xx;minr=maxr=yy;n=0
   while q:
    r,c=q.popleft();n+=1;minc=min(minc,c);maxc=max(maxc,c);minr=min(minr,r);maxr=max(maxr,r)
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
     nr,nc=r+dr,c+dc
     if 0<=nr<H and 0<=nc<W and g[nr,nc] and not seen[nr,nc]:
      seen[nr,nc]=1;q.append((nr,nc))
   comps.append((minc,maxc,minr,maxr,n))
comps.sort()
for c in comps:
    if c[4]>20:
        print('x %.1f..%.1f y %.1f..%.1f n %d'%(minx+c[0]*.15,minx+c[1]*.15,miny+(H-1-c[3])*.15,miny+(H-1-c[2])*.15,c[4]))
